import app from 'flarum/forum/app';
import Link from 'flarum/common/components/Link';
import posterUrl from 'ext:ernestdefoe/marquee/forum/utils/posterUrl';
import { t } from '../util';

/** A list as a card: up to four posters fanned out, its name and size. */
export default function ListCard(list) {
  const preview = list.preview() || [];
  return m("li", {
    className: "ShelfListCard"
  }, m(Link, {
    href: app.route('shelf.list', {
      id: list.id()
    })
  }, m("span", {
    className: "ShelfListCard-stack",
    "aria-hidden": "true"
  }, preview.length ? preview.map(p => p.poster ? m("img", {
    src: posterUrl(p.poster, 'w92'),
    alt: "",
    loading: "lazy",
    decoding: "async"
  }) : m("span", null)) : m("span", {
    className: "ShelfListCard-empty"
  })), m("b", null, list.name()), m("small", null, t('lists.items', {
    count: list.itemCount()
  }))));
}
flarum.reg.add('ernestdefoe-shelf', 'forum/components/ListCard', ListCard);